import{_ as t,o as e,c as i,a5 as n}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"RTTI・dynamic_cast・例外処理の仕組み","description":"","frontmatter":{"title":"RTTI・dynamic_cast・例外処理の仕組み","study":{"source":"C++ Wiki","status":"published","summary":"言語機能としての使い方はキャストと例外で説明済み。このページは「内部で何が起きているか」と「ゲーム開発でオフにされがちな理由」を扱います。以下は主流実装(Itanium C++ ABI / MSVC)の説明で、標準が実装方式を定めているわけではありません。","section":"reference","format":"article","domain":"runtime"}},"headers":[],"relativePath":"runtime/cpp-internals/exceptions-and-rtti-impl.md","filePath":"runtime/cpp-internals/exceptions-and-rtti-impl.md"}'),s={name:"runtime/cpp-internals/exceptions-and-rtti-impl.md"};function l(r,a,o,c,d,p){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="rtti・dynamic-cast・例外処理の仕組み" tabindex="-1">RTTI・dynamic_cast・例外処理の仕組み <a class="header-anchor" href="#rtti・dynamic-cast・例外処理の仕組み" aria-label="Permalink to &quot;RTTI・dynamic_cast・例外処理の仕組み&quot;">​</a></h1><p>言語機能としての使い方は<a href="/study/languages/cpp/casts.html">キャスト</a>と<a href="/study/languages/cpp/exceptions.html">例外</a>で説明済み。このページは「<strong>内部で何が起きているか</strong>」と「ゲーム開発でオフにされがちな理由」を扱います。以下は主流実装(Itanium C++ ABI / MSVC)の説明で、標準が実装方式を定めているわけではありません。</p><h2 id="rtti-run-time-type-information" tabindex="-1">RTTI (Run-Time Type Information) <a class="header-anchor" href="#rtti-run-time-type-information" aria-label="Permalink to &quot;RTTI (Run-Time Type Information)&quot;">​</a></h2><h3 id="何が格納されているか" tabindex="-1">何が格納されているか <a class="header-anchor" href="#何が格納されているか" aria-label="Permalink to &quot;何が格納されているか&quot;">​</a></h3><p>仮想関数を持つ型のvtableには、関数ポインタに加えて <strong>type_info への参照</strong>が置かれます(→ <a href="/study/runtime/cpp-internals/vtable-and-virtual-calls.html">vtable</a>)。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dragonのvtable</span></span>
<span class="line"><span>  [type_info*] ──&gt; &quot;6Dragon&quot; という型情報(名前、基底クラスへのリンク)</span></span>
<span class="line"><span>  [~Dragon]</span></span>
<span class="line"><span>  [Attack]...</span></span></code></pre></div><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::type_info</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> t </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> typeid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enemyPtr);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // vptr経由で実行時の型名を取得</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                       // 修飾された型名(処理系依存の文字列)</span></span></code></pre></div><h3 id="dynamic-cast-の動き" tabindex="-1">dynamic_cast の動き <a class="header-anchor" href="#dynamic-cast-の動き" aria-label="Permalink to &quot;dynamic_cast の動き&quot;">​</a></h3><p><code>dynamic_cast&lt;Dragon*&gt;(e)</code> は、eのvtableからtype_infoを取り、<strong>継承グラフを辿って</strong> Dragonに到達できるか照合します。深い階層・多重継承・仮想継承では照合が複雑になり、<strong>数十〜数百サイクル</strong>かかりえます(単純な比較ではない)。</p><h3 id="なぜゲームでオフにされがちか" tabindex="-1">なぜゲームでオフにされがちか <a class="header-anchor" href="#なぜゲームでオフにされがちか" aria-label="Permalink to &quot;なぜゲームでオフにされがちか&quot;">​</a></h3><ul><li>コスト: type_infoデータが全ポリモーフィック型に付き(サイズ)、castが遅い</li><li>代替が容易: ゲームは型階層を自分で管理できるので、<strong>自前の型ID</strong>(enumやビットマスク比較)で「1回の整数比較」に置き換えられる</li><li>実例: UEはRTTIをオフにし、リフレクション情報(<a href="/study/game/unreal/reflection-and-uht.html">UClass</a>)を使う <code>Cast&lt;T&gt;()</code> を提供。Unity(IL2CPP)のC#は独自のメタデータで型検査</li><li>コンパイラフラグ: <code>-fno-rtti</code>(GCC/Clang)、<code>/GR-</code>(MSVC)。RTTIオフだとdynamic_cast(ポリモーフィック型)とtypeidは使えない</li></ul><h2 id="例外処理の仕組み" tabindex="-1">例外処理の仕組み <a class="header-anchor" href="#例外処理の仕組み" aria-label="Permalink to &quot;例外処理の仕組み&quot;">​</a></h2><h3 id="_2大実装方式" tabindex="-1">2大実装方式 <a class="header-anchor" href="#_2大実装方式" aria-label="Permalink to &quot;2大実装方式&quot;">​</a></h3><ol><li><strong>テーブル方式(ゼロコスト例外)</strong> — Itanium ABI(Linux/Mac/近年のWindows x64も): <ul><li>各関数の「この範囲で例外が起きたらここへ」という<strong>巻き戻し表</strong>を実行ファイルに埋め込む(.eh_frame等のセクション)</li><li><strong>投げなければ実行時コストほぼゼロ</strong>(通常パスに命令が入らない)</li><li><strong>投げたら高い</strong>: 表を検索しながらスタックを1フレームずつ巻き戻し、各フレームのデストラクタを実行(<a href="/study/languages/cpp/exceptions.html">スタック巻き戻し</a>)。数千〜数万サイクル</li></ul></li><li><strong>フレーム登録方式</strong>(旧32bit Windowsなど): tryのたびに実行時登録=<strong>投げなくてもコストがかかる</strong>。「例外は遅い」という古い常識の出所の一つ</li></ol><h3 id="コストの内訳-テーブル方式でも残るもの" tabindex="-1">コストの内訳(テーブル方式でも残るもの) <a class="header-anchor" href="#コストの内訳-テーブル方式でも残るもの" aria-label="Permalink to &quot;コストの内訳(テーブル方式でも残るもの)&quot;">​</a></h3><ul><li>実行ファイルサイズ: 巻き戻し表+デストラクタ呼び出しコードの分</li><li><strong>最適化への制約</strong>: 「ここで例外が飛ぶかもしれない」が命令の並べ替え・レジスタ割当を制約する(noexcept が最適化に効く理由)</li><li>だからゲームでは <code>-fno-exceptions</code> でまるごと外す文化があった(→ <a href="/study/languages/cpp/exceptions.html">例外のページ</a>の「業界の現実」)</li></ul><h3 id="noexcept-の意味-内部視点" tabindex="-1">noexcept の意味(内部視点) <a class="header-anchor" href="#noexcept-の意味-内部視点" aria-label="Permalink to &quot;noexcept の意味(内部視点)&quot;">​</a></h3><p><code>noexcept</code> 関数から例外が漏れると<strong>即 std::terminate</strong>。コンパイラは「この関数からは飛ばない」前提で表を省略し最適化できます。<strong>ムーブコンストラクタのnoexceptはvectorの再確保がムーブを使う条件</strong>でもある(投げうるムーブでは強い例外保証のためコピーが選ばれる)——実利のあるアノテーションです。</p><h2 id="c-との対応" tabindex="-1">C#との対応 <a class="header-anchor" href="#c-との対応" aria-label="Permalink to &quot;C#との対応&quot;">​</a></h2><ul><li>C#の例外も内部はテーブル+巻き戻しで概念は近い。ただしC#はランタイムが常に型情報・スタック情報を持つため、スタックトレース取得が標準機能。C++では別途(プラットフォームAPI/ライブラリ)で取る</li><li>C#のリフレクション(<code>GetType()</code>)はRTTIの遥かに豊かな版(メンバ列挙・動的呼び出しまで)。C++のRTTIは「型の同定」しかできない最小限——UEがリフレクションを<strong>自作</strong>した理由(→ <a href="/study/game/unreal/reflection-and-uht.html">リフレクション — UCLASS・UFUNCTION・UPROPERTY・Unreal Header Tool</a>)</li></ul><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>「is/as は軽い」感覚でdynamic_castを多用しない——C++版は階層照合で重め。頻繁な型分岐は設計(仮想関数/<a href="/study/design/patterns/visitor.html">Visitor</a>/型ID)で消す</li><li>C++の <code>typeid().name()</code> は「読める型名」を保証しない(GCCでは修飾名。復元はabi::__cxa_demangle)</li><li>「例外が使えない環境がある」はC#にはない発想。ライブラリ選定時に「例外を投げるライブラリか」を見る目が要る</li></ol><h2 id="ゲーム開発での判断" tabindex="-1">ゲーム開発での判断 <a class="header-anchor" href="#ゲーム開発での判断" aria-label="Permalink to &quot;ゲーム開発での判断&quot;">​</a></h2><ul><li>RTTI・例外とも「<strong>使う/使わないをプロジェクト初期に決めて統一</strong>」が重要(混在はリンク・ABI事故の元)</li><li>自前型IDの典型実装: 基底に <code>virtual TypeId GetType() const</code> を1つ生やし、enumを返す(1整数比較で分岐)。またはコンポーネント型ごとの静的ID(→ <a href="/study/game/patterns/component-and-ecs.html">ECS</a>の型管理)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>dynamic_castが「単純な比較でない」理由は?</li><li>ゼロコスト例外の「ゼロ」と「高い」はそれぞれ何のことですか。</li><li>ムーブコンストラクタにnoexceptを付ける実利は?</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>godbolt.orgで、同じ関数を <code>-fexceptions</code> と <code>-fno-exceptions</code> でコンパイルし、生成コード・セクションサイズの違いを観察してください。また <code>-fno-rtti</code> でdynamic_castがコンパイルエラーになることを確認してください。</p><hr><p>関連項目：<a href="/study/runtime/cpp-internals/vtable-and-virtual-calls.html">vtableと仮想関数呼び出し</a> / <a href="/study/runtime/cpp-internals/">学習ガイド</a> / <a href="/study/runtime/cpp-internals/memory-layout.html">メモリレイアウト</a></p>`,30)])])}const m=t(s,[["render",l]]);export{u as __pageData,m as default};
